def rollout_audit(predict_next,history,truth):
    history=np.asarray(history,dtype=np.float64).copy()
    truth=np.asarray(truth,dtype=np.float64)
    if history.ndim!=2 or truth.ndim!=2 or history.shape[1]!=truth.shape[1]:
        raise ValueError('incompatible trajectory shapes')
    predictions=[]
    for _ in range(len(truth)):
        next_state=np.asarray(predict_next(history.copy()),dtype=np.float64)
        if next_state.shape!=history.shape[1:] or not np.isfinite(next_state).all():
            raise ValueError('invalid predicted state')
        predictions.append(next_state.copy())
        history=np.concatenate([history[1:],next_state[None]],axis=0)
    predictions=np.asarray(predictions)
    norms=np.linalg.norm(truth,axis=1)
    if np.any(norms==0):raise ValueError('zero reference norm')
    errors=np.linalg.norm(predictions-truth,axis=1)/norms
    return {'predictions':predictions,'per_step_error':errors,'field_error':float(np.linalg.norm(predictions-truth)/np.linalg.norm(truth))}
